def bellman_ref(n, edges, src):
    # edges: (u,v,w)
    dist = [float('inf')] * n
    dist[src] = 0
    for _ in range(n - 1):
        for u, v, w in edges:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
    return dist

import heapq
from collections import defaultdict

def dijkstra(n, edges, src=0):
    g = defaultdict(list)
    for u, v, w in edges:
        g[u].append((v, w))
        # g[v].append((u, w))  # if undirected
    dist = [float('inf')] * n
    dist[src] = 0
    h = [(0, src)]
    while h:
        d, u = heapq.heappop(h)
        if d != dist[u]:
            continue  # stale
        for v, w in g[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                heapq.heappush(h, (nd, v))
    return dist
